export interface Finding { title: string; source: string; reality: string; response: string }
/** Values quoted here are the original Figma values, kept as the record. */
export const findings: Finding[] = [
  { title: 'A swapped state pair', source: 'Tab Default reads #090909 and Hover #8f969d.', reality: 'In the live product the unselected tab is muted and gets darker on hover.', response: 'Corrected. Rule: when a value looks backwards, compare it with the live product.' },
  { title: 'Stale tokens', source: 'The published design-kit tokens differ from the Figma file.', reality: 'The kit is older than the file.', response: 'Prefer the file’s values over the kit’s.' },
  { title: 'Master versus instance', source: 'Master frames say Figtree at 14px.', reality: 'Instances resolve to Inter at 12px.', response: 'Inter everywhere.' },
  { title: 'An extraction blind spot', source: 'The extract keeps fills and text, not font overrides.', reality: 'Font weights were missing from the specs.', response: 'Wrote an override inspector that reads them from the raw file.' },
  { title: 'My own reading', source: 'The grid link, the chip weight and the toolbar title.', reality: 'I read all three wrong.', response: 'Fixed to the spec. Each correction became a written rule.' },
];

export interface Decision { decision: string; instead: string; why: string; cost: string }
export const decisions: Decision[] = [
  { decision: 'Intents written by hand, registry generated', instead: 'Generate or hand-write everything', why: 'Judgement cannot be generated, and facts should not be typed.', cost: 'The build fails if an intent names a component that no longer exists.' },
  { decision: 'Read the local Figma file, never the API', instead: 'A live sync', why: 'The API was rate-limited, and an offline build is repeatable.', cost: 'Specs are only as fresh as the last extract.' },
  { decision: 'Ban MUI imports in pages and templates', instead: 'A style guide', why: 'A lint rule beats a reminder.', cost: 'A missing component has to be built before a page can use it.' },
  { decision: 'One typography file with named roles', instead: 'Numeric font weights wherever needed', why: 'Weight drift was the most repeated review comment.', cost: 'Every change goes through the role and the log.' },
  { decision: 'Fix the component, never the page', instead: 'Page-level overrides', why: 'A wrong page means a wrong component.', cost: 'Slower per screen, faster overall.' },
  { decision: 'Log every deviation from Figma', instead: 'Fix quietly', why: 'An undocumented difference looks like a bug.', cost: 'A table that has to be maintained.' },
];

